// ContextQuant product dashboard preview. Plain JS, no build step. Data comes from data.js (window.CQ), generated by build_data.py.
(function () {
  'use strict';
  const CQ = window.CQ;
  const M = CQ.meta;
  const F = CQ.filings; // sorted by CSI average, highest (most stress) first
  const C = { flag: '#3fa863', base: '#5b8dd9', grid: 'rgba(255,255,255,0.08)', axis: 'rgba(255,255,255,0.22)', ink: '#a3acbd',
    muted: '#8590a3', text: '#e8ecf2', surface: '#0a1018' };
  const NS = 'http://www.w3.org/2000/svg';
  const view = document.getElementById('view');

  // ---------- helpers ----------
  const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const tip = html => ` data-tip="${esc(html)}"`;
  const sgn = (v, d = 2) => v == null ? 'n/a' : (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v).toFixed(d);
  const fx = (v, d = 2) => v == null ? 'n/a' : (v < 0 ? '−' : '') + Math.abs(v).toFixed(d);
  const pct = (v, d = 1) => v == null ? 'n/a' : (v * 100).toFixed(d) + '%';
  const median = a => { const s = a.filter(v => v != null).sort((x, y) => x - y); if (!s.length) return null; const m = s.length / 2; return s.length % 2 ? s[Math.floor(m)] : (s[m - 1] + s[m]) / 2; };
  function quantile(a, q) { // linear interpolation, as pandas
    const s = a.filter(v => v != null).sort((x, y) => x - y); const pos = (s.length - 1) * q; const lo = Math.floor(pos), hi = Math.ceil(pos);
    return s[lo] + (s[hi] - s[lo]) * (pos - lo);
  }
  function el(tag, attrs, parent) { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); if (parent) parent.appendChild(e); return e; }
  function txt(parent, x, y, s, attrs) { const t = el('text', Object.assign({ x, y, 'font-size': 12, fill: C.ink }, attrs || {}), parent); t.textContent = s; return t; }
  function svgIn(box, W, H, label) { box.innerHTML = ''; return el('svg', { width: W, height: H, viewBox: `0 0 ${W} ${H}`, role: 'img', 'aria-label': label }, box); }
  // Bar path: square at baseline, 4px rounded data end.
  function hbar(x0, y, w, h) { const r = Math.min(4, w, h / 2); return `M${x0},${y} H${x0 + w - r} Q${x0 + w},${y} ${x0 + w},${y + r} V${y + h - r} Q${x0 + w},${y + h} ${x0 + w - r},${y + h} H${x0} Z`; }
  function vbar(x, base, top, w) { const h = base - top, r = Math.min(4, h, w / 2); return `M${x},${base} V${top + r} Q${x},${top} ${x + r},${top} H${x + w - r} Q${x + w},${top} ${x + w},${top + r} V${base} Z`; }

  const SECTOR = k => (CQ.sectors[k] || {}).name || 'Unknown';
  const SHORT = { 1: 'Non-durables', 2: 'Durables', 3: 'Manufacturing', 4: 'Energy', 5: 'Chemicals', 6: 'Tech and equipment', 7: 'Telecom, media', 8: 'Utilities', 9: 'Retail', 10: 'Healthcare', 11: 'Finance', 12: 'Other' };
  const CNT = ['Liquidity and funding', 'Risk factors added', 'Risk factors removed', 'Guidance lowered', 'Guidance raised', 'Headwinds', 'Tailwinds', 'Severe items'];
  const CNT_SHORT = ['liquidity', 'risk added', 'risk removed', 'guidance lowered', 'guidance raised', 'headwind', 'tailwind', 'severe'];
  // Full-reading fields: label, scale note, which direction is worse (-1 lower worse, 1 higher worse, 0 neutral)
  const FIELDS = [
    ['Change vs previous filing', '-1 worse to +1 better', -1], ['Net tone', '-1 to +1', -1], ['Liquidity stress', '-1 easing to +1 rising', 1],
    ['Guidance direction', '-1 lowered to +1 raised', -1], ['Demand outlook', '-1 to +1', -1], ['Margin pressure', '-1 easing to +1 rising', 1],
    ['Pricing power', '-1 to +1', -1], ['Inventory risk', '-1 falling to +1 rising', 1], ['Prominence of risk language', '0 to 1', 1],
    ['Uncertainty', '0 to 1', 1], ['Hedging', '0 to 1', 1], ['Management confidence', '0 to 1', -1],
    ['Words vs numbers', '-1 words more negative to +1 more positive', 0], ['Forward-looking share', '0 to 1', 0],
    ['Guidance specificity', '0 to 1', 0], ['Call candour', '0 to 1, blank without a call', -1]];
  const PEER = [['Tone vs competitors', '-1 to +1', -1], ['Outlook vs competitors', '-1 to +1', -1], ['Rank among competitors', '1 = best', 1]];

  // ---------- precomputed set statistics ----------
  F.forEach((f, i) => { f.rank = i + 1; f.cs = f.a[0]; });
  const byCs = F.slice().sort((x, y) => x.cs - y.cs); // worst first
  const csRank = new Map(); byCs.forEach((f, i) => { if (i === 0 || f.cs !== byCs[i - 1].cs) csRank.set(f.cs, i + 1); });
  const byAcc = new Map(F.map(f => [f.acc, f]));
  const latest = new Map(); F.forEach(f => { const p = latest.get(f.t); if (!p || f.fd > p.fd) latest.set(f.t, f); });
  const byTicker = new Map(); F.forEach(f => { if (!byTicker.has(f.t)) byTicker.set(f.t, []); byTicker.get(f.t).push(f); });
  byTicker.forEach(a => a.sort((x, y) => y.fd.localeCompare(x.fd)));
  const allCsi = F.map(f => f.csi), allCs = F.map(f => f.cs);
  const setMedA = FIELDS.map((_, i) => median(F.map(f => f.a[i])));
  const setMedB = FIELDS.map((_, i) => median(F.map(f => f.b[i]))).concat(PEER.map((_, j) => median(F.map(f => f.b[16 + j]))));
  const cntP90 = CNT.map((_, i) => quantile(F.map(f => f.cnt[i]), 0.9));
  const sectorStats = {};
  Object.keys(CQ.sectors).forEach(k => {
    const fs = F.filter(f => String(f.sec) === k);
    sectorStats[k] = { n: fs.length, csiMed: median(fs.map(f => f.csi)), csMed: median(fs.map(f => f.cs)),
      cntMed: CNT.map((_, i) => median(fs.map(f => f.cnt[i]))), fc: fs.filter(f => f.fc).length, fs: fs.filter(f => f.fs).length,
      any: fs.filter(f => f.fc || f.fs).length };
  });
  const dryByTicker = new Map(); CQ.dry.forEach(d => { if (!dryByTicker.has(d.t)) dryByTicker.set(d.t, []); dryByTicker.get(d.t).push(d); });

  document.getElementById('period').textContent = `Current set: ${M.n_filings} filings filed ${M.filed_from} to ${M.filed_to}`;

  // ---------- tooltip ----------
  const tipEl = document.getElementById('tip');
  function placeTip(e) {
    const pad = 14, w = tipEl.offsetWidth, h = tipEl.offsetHeight;
    let x = e.clientX + pad, y = e.clientY + pad;
    if (x + w > window.innerWidth - 8) x = Math.max(8, e.clientX - w - pad);
    if (y + h > window.innerHeight - 8) y = Math.max(8, e.clientY - h - pad);
    tipEl.style.left = x + 'px'; tipEl.style.top = y + 'px';
  }
  document.addEventListener('mouseover', e => { const t = e.target.closest && e.target.closest('[data-tip]'); if (!t) { tipEl.style.display = 'none'; return; }
    tipEl.innerHTML = t.getAttribute('data-tip'); tipEl.style.display = 'block'; placeTip(e); });
  document.addEventListener('mousemove', e => { if (tipEl.style.display === 'block') placeTip(e); });
  document.addEventListener('scroll', () => { tipEl.style.display = 'none'; }, true);

  // ---------- small shared pieces ----------
  function flagBadges(f, compact) {
    const b = [];
    if (f.fc) b.push(`<span class="badge flag"${tip('Credit Stress Index in the worst tenth of the current set (at or above ' + fx(M.csi_cut) + ')')}>${compact ? 'CSI' : 'CSI flag'}</span>`);
    if (f.fs) b.push(`<span class="badge flag"${tip('Change Signal in the worst tenth of the current set (at or below ' + fx(M.cs_cut) + ')')}>${compact ? 'Change' : 'Change flag'}</span>`);
    return b.join(' ');
  }
  function ibar(v, range, flagged, tipHtml, d) {
    const w = Math.min(50, Math.abs(v) / range * 50);
    return `<span class="ibar"${tip(tipHtml)}><span class="track"><span class="fill ${v >= 0 ? 'pos' : 'neg'}${flagged ? ' f' : ''}" style="width:${w}%"></span></span><span class="val">${sgn(v, d)}</span></span>`;
  }
  const lockBadge = `<span class="badge lock"${tip('Scores locked in November 2026 (SHA-256 ' + M.sha_csi_avg.slice(0, 8) + '...). Downgrade outcomes for these filings do not exist yet.')}>Scores locked Nov 2026, outcomes pending</span>`;
  const ruleBox = `<div class="rule"><b>Flag rule.</b> A filing is flagged when a reading falls in the worst tenth of the ${M.n_filings} filings in the current set, ties at the cut-off included: Credit Stress Index at or above ${fx(M.csi_cut)} (${M.n_flag_csi} filings), Change Signal at or below ${fx(M.cs_cut)} (${M.n_flag_cs} filings, more than a tenth because many filings share the cut-off value). ${M.n_flag_both} filings are flagged by both.</div>`;
  function csiTip(f) { return `<b>${esc(f.t)}</b> Credit Stress Index ${sgn(f.csi)}<br><span class="m">Rank ${f.rank} of ${M.n_filings}; average of three readings (${f.csi3.map(v => sgn(v)).join(', ')})</span>`; }
  function csTip(f) { return `<b>${esc(f.t)}</b> Change Signal ${sgn(f.cs)}<br><span class="m">Below 0: this filing reads worse than the previous one. Rank ${csRank.get(f.cs)} of ${M.n_filings} (ties share a rank)</span>`; }

  // ---------- charts ----------
  // Strip: every filing in the set as a faint dot, worst-tenth zone, sector median tick, this filing as a ringed dot.
  function stripChart(box, o) {
    const W = Math.max(260, box.clientWidth), H = 74, m = { l: 8, r: 8, t: 10, b: 22 };
    const svg = svgIn(box, W, H, o.label);
    const x = v => m.l + (W - m.l - m.r) * (v - o.lo) / (o.hi - o.lo);
    const y0 = m.t, y1 = H - m.b;
    const z0 = x(o.zone[0]), z1 = x(o.zone[1]);
    el('rect', { x: Math.min(z0, z1), y: y0, width: Math.abs(z1 - z0), height: y1 - y0, fill: 'rgba(63,168,99,0.10)', rx: 3 }, svg);
    el('line', { x1: m.l, x2: W - m.r, y1: y1, y2: y1, stroke: C.axis }, svg);
    o.ticks.forEach(t => { el('line', { x1: x(t), x2: x(t), y1: y1, y2: y1 + 4, stroke: C.axis }, svg);
      txt(svg, x(t), H - 6, (t > 0 ? '+' : t < 0 ? '−' : '') + Math.abs(t), { 'text-anchor': t === o.lo ? 'start' : t === o.hi ? 'end' : 'middle', 'font-size': 11, fill: C.muted }); });
    o.values.forEach((v, i) => { const j = ((i * 7919) % 97) / 97; el('circle', { cx: x(v) + (j - 0.5) * 2, cy: y0 + 6 + j * (y1 - y0 - 12), r: 1.8, fill: 'rgba(163,172,189,0.32)' }, svg); });
    if (o.med != null) { const mx = x(o.med); el('line', { x1: mx, x2: mx, y1: y0 - 2, y2: y1, stroke: C.text, 'stroke-width': 2, 'stroke-linecap': 'round' }, svg);
      el('rect', { x: mx - 7, y: y0 - 4, width: 14, height: y1 - y0 + 6, fill: 'transparent', 'data-tip': `<b>Sector median</b> ${sgn(o.med)}<br><span class="m">${esc(o.sectorName)}, current set</span>` }, svg); }
    const cx = x(o.v), cy = (y0 + y1) / 2;
    el('circle', { cx, cy, r: 6, fill: C.base, stroke: C.surface, 'stroke-width': 2 }, svg);
    el('circle', { cx, cy, r: 12, fill: 'transparent', 'data-tip': o.tip }, svg);
  }

  // Horizontal count bars with a sector-median tick.
  function countBars(box, rows) {
    const W = Math.max(280, box.clientWidth), rowH = 28, labW = Math.min(160, W * 0.42), valW = 34;
    const H = rows.length * rowH + 8; const svg = svgIn(box, W, H, 'Item counts by type');
    const max = Math.max(4, ...rows.map(r => Math.max(r.v, r.med || 0)));
    const x0 = labW, span = W - labW - valW - 6;
    rows.forEach((r, i) => {
      const y = i * rowH + 4;
      txt(svg, 0, y + 15, r.label, { fill: r.v > 0 ? C.ink : C.muted, 'font-size': 12.5 });
      el('rect', { x: x0, y: y + 7, width: span, height: 12, fill: 'rgba(255,255,255,0.03)', rx: 3 }, svg);
      if (r.v > 0) el('path', { d: hbar(x0, y + 7, span * r.v / max, 12), fill: r.hi ? C.flag : C.base }, svg);
      if (r.med != null) { const mx = x0 + span * r.med / max; el('line', { x1: mx, x2: mx, y1: y + 3, y2: y + 23, stroke: C.text, 'stroke-width': 2, 'stroke-linecap': 'round' }, svg); }
      txt(svg, W - 2, y + 17, String(r.v), { 'text-anchor': 'end', fill: C.text, 'font-family': 'DM Mono, monospace', 'font-size': 12.5 });
      el('rect', { x: 0, y, width: W, height: rowH, fill: 'transparent', 'data-tip': `<b>${esc(r.label)}</b>: ${r.v} item${r.v === 1 ? '' : 's'}<br><span class="m">Sector median ${r.med == null ? 'n/a' : r.med}; top tenth of the set from ${r.p90}${r.hi ? '. This filing is in the top tenth.' : ''}</span>` }, svg);
    });
  }

  // Profile rows: sector 10th to 90th percentile band, sector median tick, company dot.
  function rangeRows(box, rows) {
    const W = Math.max(280, box.clientWidth), narrow = W < 520, rowH = narrow ? 46 : 34;
    const labW = narrow ? 0 : Math.min(230, W * 0.34), valW = 70;
    const H = rows.length * rowH + 6; const svg = svgIn(box, W, H, 'Company profile against its sector');
    rows.forEach((r, i) => {
      const y = i * rowH + 3, by = narrow ? y + 22 : y + 10;
      txt(svg, 0, narrow ? y + 13 : y + 21, r.label, { fill: C.ink, 'font-size': 12.5 });
      const vals = [r.p10, r.med, r.p90, r.v].filter(v => v != null);
      if (!vals.length) { txt(svg, labW, by + 10, 'not available', { fill: C.muted }); return; }
      let lo = Math.min(...vals), hi = Math.max(...vals); const pad = (hi - lo) * 0.08 || 1; lo -= pad; hi += pad;
      const x0 = labW, span = W - labW - valW - 10, x = v => x0 + span * (v - lo) / (hi - lo);
      if (r.p10 != null && r.p90 != null) el('rect', { x: x(r.p10), y: by, width: Math.max(2, x(r.p90) - x(r.p10)), height: 14, rx: 7, fill: 'rgba(255,255,255,0.10)' }, svg);
      if (r.med != null) el('line', { x1: x(r.med), x2: x(r.med), y1: by - 3, y2: by + 17, stroke: C.text, 'stroke-width': 2, 'stroke-linecap': 'round' }, svg);
      if (r.v != null) el('circle', { cx: x(r.v), cy: by + 7, r: 6, fill: C.base, stroke: C.surface, 'stroke-width': 2 }, svg);
      txt(svg, W - 2, narrow ? y + 13 : y + 21, r.v == null ? 'n/a' : r.fmt(r.v), { 'text-anchor': 'end', fill: C.text, 'font-family': 'DM Mono, monospace', 'font-size': 12.5 });
      el('rect', { x: 0, y, width: W, height: rowH, fill: 'transparent', 'data-tip': `<b>${esc(r.label)}</b><br>This company: ${r.v == null ? 'n/a' : r.fmt(r.v)}<br>Sector median: ${r.med == null ? 'n/a' : r.fmt(r.med)}<br><span class="m">Sector 10th to 90th percentile: ${r.p10 == null ? 'n/a' : r.fmt(r.p10)} to ${r.p90 == null ? 'n/a' : r.fmt(r.p90)}. Riskier when ${r.riskier}.</span>` }, svg);
    });
  }

  // Grouped columns, two series, one axis.
  function groupedBars(box, groups, o) {
    const W = Math.max(300, box.clientWidth), H = 300, m = { t: 26, r: 8, b: 48, l: 44 };
    const svg = svgIn(box, W, H, o.label);
    const max = Math.ceil(Math.max(...groups.flatMap(g => [g.a, g.b])) * 100 / 5) * 5 / 100 || 0.05;
    const y = v => m.t + (H - m.t - m.b) * (1 - v / max);
    for (let v = 0; v <= max + 1e-9; v += max > 0.2 ? 0.05 : 0.025) {
      el('line', { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v), stroke: v === 0 ? C.axis : C.grid }, svg);
      txt(svg, m.l - 8, y(v) + 4, Math.round(v * 1000) / 10 + '%', { 'text-anchor': 'end', 'font-size': 11, fill: C.muted });
    }
    const gw = (W - m.l - m.r) / groups.length, bw = Math.min(24, gw * 0.22), gap = 4;
    groups.forEach((g, i) => {
      const cx = m.l + gw * i + gw / 2;
      [[g.a, C.flag, cx - bw - gap / 2, g.tipA], [g.b, C.base, cx + gap / 2, g.tipB]].forEach(([v, col, bx, t]) => {
        el('path', { d: vbar(bx, y(0), y(v), bw), fill: col }, svg);
        txt(svg, bx + bw / 2, y(v) - 7, (v * 100).toFixed(1) + '%', { 'text-anchor': 'middle', fill: C.text, 'font-size': 12, 'font-family': 'DM Mono, monospace' });
        el('rect', { x: bx - 6, y: m.t - 20, width: bw + 12, height: y(0) - m.t + 20, fill: 'transparent', 'data-tip': t }, svg);
      });
      txt(svg, cx, H - m.b + 20, gw < 130 && g.label === 'Credit Stress Index' ? 'CSI' : g.label, { 'text-anchor': 'middle', fill: C.ink, 'font-size': 12.5 });
      if (g.sub) txt(svg, cx, H - m.b + 36, gw < 150 ? g.subShort : g.sub, { 'text-anchor': 'middle', fill: C.muted, 'font-size': 11 });
    });
  }

  // Two-series line chart with crosshair tooltip and end labels.
  function lineChart(box, xs, series, o) {
    const W = Math.max(300, box.clientWidth), narrow = W < 560, H = 290, m = { t: 18, r: narrow ? 24 : 160, b: 40, l: narrow ? 52 : 100 };
    const svg = svgIn(box, W, H, o.label);
    const all = series.flatMap(s => s.values); let lo = Math.min(...all, 0), hi = Math.max(...all, 0);
    const step = o.step; lo = Math.floor(lo / step) * step; hi = Math.ceil(hi / step) * step;
    const x = i => m.l + (W - m.l - m.r) * i / (xs.length - 1), y = v => m.t + (H - m.t - m.b) * (1 - (v - lo) / (hi - lo));
    for (let v = lo; v <= hi + 1e-9; v += step) {
      el('line', { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v), stroke: Math.abs(v) < 1e-9 ? C.axis : C.grid }, svg);
      txt(svg, m.l - 8, y(v) + 4, sgn(v, o.dp), { 'text-anchor': 'end', 'font-size': 11, fill: C.muted });
    }
    xs.forEach((l, i) => txt(svg, x(i), H - 14, narrow ? l.short : l.long, { 'text-anchor': 'middle', 'font-size': 11.5, fill: C.ink }));
    series.forEach(s => {
      el('path', { d: s.values.map((v, i) => (i ? 'L' : 'M') + x(i) + ',' + y(v)).join(' '), fill: 'none', stroke: s.color, 'stroke-width': 2, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }, svg);
      s.values.forEach((v, i) => el('circle', { cx: x(i), cy: y(v), r: 4.5, fill: s.color, stroke: C.surface, 'stroke-width': 2 }, svg));
      if (!narrow) { const last = s.values[s.values.length - 1]; txt(svg, x(xs.length - 1) + 12, y(last) + 4, s.name, { fill: C.text, 'font-size': 12 }); }
    });
    const cross = el('line', { y1: m.t, y2: H - m.b, stroke: 'rgba(255,255,255,0.28)', visibility: 'hidden' }, svg);
    const hit = el('rect', { x: m.l - 10, y: m.t, width: W - m.l - m.r + 20, height: H - m.t - m.b, fill: 'transparent' }, svg);
    const idx = e => { const r = svg.getBoundingClientRect(); const px = (e.clientX - r.left) * W / r.width; return Math.max(0, Math.min(xs.length - 1, Math.round((px - m.l) / ((W - m.l - m.r) / (xs.length - 1))))); };
    hit.addEventListener('mousemove', e => { const i = idx(e); cross.setAttribute('x1', x(i)); cross.setAttribute('x2', x(i)); cross.setAttribute('visibility', 'visible');
      tipEl.innerHTML = `<b>${xs[i].long}</b><br>` + series.map(s => `${esc(s.name)}: ${sgn(s.values[i], 3)} <span class="m">(${s.ns[i].toLocaleString('en-US')} filings)</span>`).join('<br>');
      tipEl.style.display = 'block'; placeTip(e); });
    hit.addEventListener('mouseleave', () => { cross.setAttribute('visibility', 'hidden'); tipEl.style.display = 'none'; });
  }

  // ---------- view 1: watch list ----------
  const W1 = { q: '', sec: 'all', flag: 'all', sort: 'csi', shown: 100 };
  function watchRows() {
    const q = W1.q.trim().toUpperCase();
    let rows = F.filter(f => (W1.sec === 'all' || String(f.sec) === W1.sec)
      && (W1.flag === 'all' || (W1.flag === 'any' && (f.fc || f.fs)) || (W1.flag === 'csi' && f.fc) || (W1.flag === 'cs' && f.fs) || (W1.flag === 'both' && f.fc && f.fs))
      && (!q || f.t.toUpperCase().startsWith(q) || f.n.toUpperCase().includes(q)));
    if (W1.sort === 'cs') rows = rows.slice().sort((x, y) => x.cs - y.cs || y.csi - x.csi);
    if (W1.sort === 'date') rows = rows.slice().sort((x, y) => y.fd.localeCompare(x.fd) || y.csi - x.csi);
    if (W1.sort === 'ticker') rows = rows.slice().sort((x, y) => x.t.localeCompare(y.t));
    return rows;
  }
  function renderWatch() {
    const secOpts = Object.keys(CQ.sectors).map(k => `<option value="${k}"${W1.sec === k ? ' selected' : ''}>${esc(SECTOR(k))} (${sectorStats[k].n})</option>`).join('');
    view.innerHTML = `
      <div class="head-row"><div><div class="eyebrow">1 &middot; Watch list, current quarter</div><h1>Filings ranked by credit stress</h1></div>${lockBadge}</div>
      <p class="lede">Every periodic filing made from ${M.filed_from} to ${M.filed_to} in the coverage universe, read after the language model's training ended. Ranked by the Credit Stress Index, with the Change Signal beside it. Click a row for the company view.</p>
      <div class="tiles">
        <div class="tile"><div class="l">Filings read</div><div class="v">${M.n_filings}</div><div class="d">${M.n_companies} companies</div></div>
        <div class="tile"><div class="l">Flagged by Credit Stress Index</div><div class="v">${M.n_flag_csi}</div><div class="d">worst tenth of the set</div></div>
        <div class="tile"><div class="l">Flagged by Change Signal</div><div class="v">${M.n_flag_cs}</div><div class="d">worse than the last filing</div></div>
        <div class="tile"><div class="l">Flagged by both</div><div class="v">${M.n_flag_both}</div><div class="d">${M.n_flag_any} flagged by either</div></div>
      </div>
      ${ruleBox}
      <div class="controls">
        <input type="text" id="wq" class="grow" placeholder="Search ticker or company" value="${esc(W1.q)}" aria-label="Search ticker or company">
        <select id="wsec" aria-label="Sector"><option value="all">All sectors</option>${secOpts}</select>
        <select id="wflag" aria-label="Flag filter">
          <option value="all">All filings</option><option value="any">Flagged by either</option><option value="csi">Flagged by CSI</option>
          <option value="cs">Flagged by Change Signal</option><option value="both">Flagged by both</option></select>
        <select id="wsort" aria-label="Sort"><option value="csi">Sort: Credit Stress Index</option><option value="cs">Sort: Change Signal</option>
          <option value="date">Sort: newest filing</option><option value="ticker">Sort: ticker</option></select>
      </div>
      <div class="count" id="wcount"></div>
      <div class="table-wrap" style="margin-top:8px"><table class="watch">
        <thead><tr><th class="num hide-s"${tip('Rank by Credit Stress Index in the whole set')}>#</th><th>Company</th><th class="hide-m">Sector</th><th class="hide-s">Filed</th>
        <th${tip('Credit Stress Index, average of three readings. 0 is the set average; higher means more credit-relevant disclosures.')}><span class="hide-s">Credit Stress Index</span><span class="only-s-i">CSI</span></th>
        <th${tip('Change Signal: is this filing worse than the previous one? From -1 (much worse) to +1 (much better).')}><span class="hide-s">Change Signal</span><span class="only-s-i">Change</span></th><th class="hide-s">Flags</th></tr></thead>
        <tbody id="wbody"></tbody></table></div>
      <button class="btn ghost more" id="wmore">Show more</button>
      <p class="muted" style="margin-top:14px">Change Signal evidence so far comes from 139 rated Dow 30 and semiconductor companies; elsewhere in this set it is scored the same way but not yet tested. Credit Stress Index tests are pooled across all universes. Readouts for these filings: credit when at least 30 post-cutoff downgrades exist (expected late 2027).</p>`;
    const set = (id, k) => { const e = document.getElementById(id); e.value = W1[k]; e.addEventListener(id === 'wq' ? 'input' : 'change', () => { W1[k] = e.value; W1.shown = 100; fillWatch(); }); };
    set('wq', 'q'); set('wsec', 'sec'); set('wflag', 'flag'); set('wsort', 'sort');
    document.getElementById('wmore').addEventListener('click', () => { W1.shown += 150; fillWatch(); });
    document.getElementById('wbody').addEventListener('click', e => { const tr = e.target.closest('tr[data-acc]'); if (tr) location.hash = '#company/' + tr.dataset.acc; });
    fillWatch();
  }
  function fillWatch() {
    const rows = watchRows(), show = rows.slice(0, W1.shown);
    document.getElementById('wcount').textContent = `Showing ${show.length} of ${rows.length} filings` + (rows.length < F.length ? ` (filtered from ${F.length})` : '');
    document.getElementById('wbody').innerHTML = show.map(f => `<tr class="click" data-acc="${esc(f.acc)}">
      <td class="num hide-s">${f.rank}</td>
      <td><span class="tk">${esc(f.t)}</span><span class="nm">${esc(f.n)}</span><span class="badges only-s">${flagBadges(f, true)}</span></td>
      <td class="hide-m" style="white-space:nowrap"${tip(esc(SECTOR(f.sec)))}>${esc(SHORT[f.sec])}</td><td class="mono hide-s">${esc(f.fd)}<span class="nm">${esc(f.form)}</span></td>
      <td>${ibar(f.csi, 8.5, f.fc, csiTip(f))}</td><td>${ibar(f.cs, 1, f.fs, csTip(f), 2)}</td>
      <td class="hide-s"><span class="badges" style="flex-wrap:nowrap">${flagBadges(f, true)}</span></td></tr>`).join('') || `<tr><td colspan="7">No filings match these filters.</td></tr>`;
    document.getElementById('wmore').style.display = rows.length > show.length ? 'block' : 'none';
  }

  // ---------- view 2: company ----------
  function renderCompany(acc) {
    const f = byAcc.get(acc) || F[0];
    const ss = sectorStats[f.sec] || {}; const prof = CQ.profiles[f.id]; const sp = CQ.sectors[f.sec];
    const others = (byTicker.get(f.t) || []).filter(g => g.acc !== f.acc);
    const dry = dryByTicker.get(f.t) || [];
    const datalist = [...latest.values()].sort((x, y) => x.t.localeCompare(y.t)).map(g => `<option value="${esc(g.t)}">${esc(g.n)}</option>`).join('');
    const csPctWorse = Math.round((csRank.get(f.cs) - 1) / F.length * 100);
    view.innerHTML = `
      <a class="back" href="#watch">&larr; Watch list</a>
      <div class="co-head">
        <div><div class="eyebrow">2 &middot; Company view</div><h1>${esc(f.n)}</h1>
          <div class="meta"><span><b>${esc(f.t)}</b></span><span>${esc(SECTOR(f.sec))}</span><span>${esc(f.form)} filed <b>${esc(f.fd)}</b></span><span>period ${esc(f.per)}</span>
          <span>earnings call ${f.tr ? 'included' : 'not available'}</span><span>${f.comp} competitor${f.comp === 1 ? '' : 's'} compared</span></div>
          <div class="badges" style="margin-top:10px">${flagBadges(f) || '<span class="badge ok">Not flagged</span>'} ${lockBadge}</div>
          ${others.length ? `<div class="other-filings muted" style="margin-top:8px">Other filings in the current set: ${others.map(g => `<a href="#company/${esc(g.acc)}">${esc(g.form)} ${esc(g.fd)}</a>`).join('')}</div>` : ''}
        </div>
        <div style="min-width:220px"><label class="muted" for="cpick">Open another company</label><br>
          <input type="text" id="cpick" list="cplist" placeholder="Type a ticker" style="width:220px;margin-top:4px"><datalist id="cplist">${datalist}</datalist></div>
      </div>

      <div class="grid2 sec">
        <div class="panel"><h2>Credit Stress Index</h2><div class="sub">Average of three readings; 0 is the set average, higher means more stress</div>
          <div class="reading"><div class="big">${sgn(f.csi)}</div>
          <div class="row"><span>rank ${f.rank} of ${F.length}</span><span>more stress than ${Math.floor((F.length - f.rank) / F.length * 100)}% of filings</span><span>sector median ${sgn(ss.csiMed)}</span></div>
          <div class="row"><span>three readings: ${f.csi3.map(v => sgn(v)).join(', ')}</span></div></div>
          <div class="chart" id="stripCsi" style="margin-top:8px"></div>
          <div class="legend"><span><i class="dot" style="background:${C.base}"></i>this filing</span><span><i class="tick"></i>sector median</span><span><i class="dot" style="background:rgba(163,172,189,0.5);width:6px;height:6px"></i>all ${F.length} filings</span><span><i style="background:rgba(63,168,99,0.25)"></i>flag zone (worst tenth)</span></div>
        </div>
        <div class="panel"><h2>Change Signal</h2><div class="sub">Is this filing worse than the company's previous one? -1 much worse to +1 much better</div>
          <div class="reading"><div class="big">${sgn(f.cs, 2)}</div>
          <div class="row"><span>${csPctWorse}% of filings read worse</span><span>sector median ${sgn(ss.csMed)}</span><span>with competitors in view ${sgn(f.b[0])}</span></div>
          <div class="row"><span>${f.cs < 0 ? 'Reads worse than the previous filing' : f.cs > 0 ? 'Reads better than the previous filing' : 'Reads about the same as the previous filing'}</span></div></div>
          <div class="chart" id="stripCs" style="margin-top:8px"></div>
          <div class="legend"><span><i class="dot" style="background:${C.base}"></i>this filing</span><span><i class="tick"></i>sector median</span><span><i class="dot" style="background:rgba(163,172,189,0.5);width:6px;height:6px"></i>all ${F.length} filings</span><span><i style="background:rgba(63,168,99,0.25)"></i>flag zone (worst tenth)</span></div>
        </div>
      </div>

      <div class="grid2 sec">
        <div class="panel"><h2>Credit-relevant disclosures counted</h2><div class="sub">Items per type behind the Credit Stress Index (first of the three readings). Green bars: top tenth of the set for that type.</div>
          <div class="chart" id="counts"></div>
          <div class="legend"><span><i style="background:${C.base}"></i>items in this filing</span><span><i style="background:${C.flag}"></i>top tenth of the set</span><span><i class="tick"></i>sector median</span></div>
        </div>
        <div class="panel"><h2>Evidence passages</h2><div class="sub">The quoted passages behind each counted item</div>
          <div class="placeholder"><b>In the product, each counted item links to the quoted passage in the filing.</b> The passages for this filing are held in the research database and are not part of this mock-up, so the counts are shown without quotes.
            <div class="ph-list">${f.cnt.map((c, i) => c > 0 ? `<div class="ph-item"><span class="lab">${CNT[i]} &middot; ${c}</span><span class="bar" aria-hidden="true"></span></div>` : '').join('') || '<div class="muted">No items counted in this filing.</div>'}</div>
          </div>
          ${dry.length ? `<p class="muted" style="margin-top:10px">An earlier ${esc(f.t)} filing is in the research sample with real verified quotes: ${dry.map(d => `<a href="#evidence/${encodeURIComponent(d.key)}">filing of ${esc(d.fd)} (${d.items.length} quotes)</a>`).join(', ')}.</p>` : ''}
        </div>
      </div>

      <div class="panel sec"><h2>Full reading</h2><div class="sub">Each field read from the whole filing, five quarters of financial statements, the previous filing's discussion and risk factors and the latest earnings call; the second column also sees up to four competitors' filings. Set median across all ${F.length} filings.</div>
        <div class="table-wrap" style="border:0"><table><thead><tr><th>Field</th><th class="hide-s">Scale</th><th class="num">Own<span class="hide-s"> context</span></th><th class="num">With <span class="hide-s">competitors</span><span class="only-s-i">peers</span></th><th class="num hide-s">Set median</th><th><span class="hide-s">Against median</span><span class="only-s-i">vs median</span></th></tr></thead>
        <tbody>${FIELDS.map((d, i) => fieldRow(d, f.a[i], f.b[i], setMedA[i])).join('')}${PEER.map((d, j) => fieldRow(d, null, f.b[16 + j], setMedB[16 + j], true)).join('')}</tbody></table></div>
      </div>

      <div class="panel sec"><h2>Volatility and credit fundamentals against the sector</h2>
        <div class="sub">${prof ? `Median across ${prof.fil} filings of this company in the research sample (2015 to 2026), against ${esc(SECTOR(f.sec))}: ${sp ? sp.cos + ' companies, ' + sp.fil.toLocaleString('en-US') + ' filings' : ''}.` : 'No market and accounting profile for this company in the research sample.'}</div>
        ${prof ? `<div class="chart" id="profile"></div><div class="legend"><span><i class="dot" style="background:${C.base}"></i>this company</span><span><i class="tick"></i>sector median</span><span><i class="band"></i>sector 10th to 90th percentile</span></div>` : ''}
      </div>`;
    const cp = document.getElementById('cpick');
    cp.addEventListener('change', () => { const g = latest.get(cp.value.trim().toUpperCase()); if (g) location.hash = '#company/' + g.acc; });
    cp.addEventListener('keydown', e => { if (e.key === 'Enter') { const g = latest.get(cp.value.trim().toUpperCase()); if (g) location.hash = '#company/' + g.acc; } });
    drawCompany(f, ss, prof, sp);
  }
  function fieldRow(d, a, b, med, peer) {
    const v = peer ? b : a; let cmp = '<span class="muted">n/a</span>';
    if (v != null && med != null && d[2] !== 0) { const diff = (v - med) * d[2]; cmp = Math.abs(v - med) < 0.05 ? '<span class="muted">in line</span>' : diff > 0 ? '<span class="badge hit">worse</span>' : '<span class="badge ok">better</span>'; }
    else if (d[2] === 0 && v != null) cmp = '<span class="muted">descriptive</span>';
    const fmt = val => val == null ? '<span class="muted">n/a</span>' : (peer && d[0].startsWith('Rank') ? String(val) : sgn(val));
    return `<tr><td>${esc(d[0])}</td><td class="hide-s muted">${esc(d[1])}</td><td class="num">${peer ? '<span class="muted">n/a</span>' : fmt(a)}</td><td class="num">${fmt(b)}</td><td class="num hide-s">${med == null ? 'n/a' : (peer && d[0].startsWith('Rank') ? med : sgn(med))}</td><td>${cmp}</td></tr>`;
  }
  function drawCompany(f, ss, prof, sp) {
    stripChart(document.getElementById('stripCsi'), { label: 'Credit Stress Index of this filing among all filings', values: allCsi, lo: -8, hi: 9, ticks: [-8, -4, 0, 4, 8],
      zone: [M.csi_cut, 9], med: ss.csiMed, v: f.csi, sectorName: SECTOR(f.sec), tip: csiTip(f) });
    stripChart(document.getElementById('stripCs'), { label: 'Change Signal of this filing among all filings', values: allCs, lo: -1, hi: 1, ticks: [-1, -0.5, 0, 0.5, 1],
      zone: [-1, M.cs_cut], med: ss.csMed, v: f.cs, sectorName: SECTOR(f.sec), tip: csTip(f) });
    countBars(document.getElementById('counts'), CNT.map((l, i) => ({ label: l, v: f.cnt[i], med: ss.cntMed ? ss.cntMed[i] : null, p90: cntP90[i], hi: f.cnt[i] > 0 && f.cnt[i] >= cntP90[i] })));
    if (prof && sp) {
      const P = (v, d = 1) => (v * 100).toFixed(d) + '%', N = (v, d = 2) => fx(v, d);
      const rows = [
        ['Volatility, 250 days (annualised)', 'vol', P, 'higher'], ['Deepest fall within 250 days', 'fall', P, 'lower (deeper)'], ['Market beta', 'beta', N, 'higher'],
        ['Downside beta', 'dbeta', N, 'higher'], ['Distance to default', 'dd', v => fx(v, 1), 'lower'], ['Altman Z', 'altman', N, 'lower'],
        ['Ohlson O', 'ohlson', N, 'higher'], ['Leverage', 'lev', N, 'higher'], ['Interest coverage', 'icov', v => fx(v, 1) + 'x', 'lower'], ['Volatility of return on assets', 'sdroa', v => P(v, 2), 'higher']];
      rangeRows(document.getElementById('profile'), rows.map(([label, k, fmt, riskier]) => ({ label, v: prof[k], p10: sp[k][0], med: sp[k][1], p90: sp[k][2], fmt, riskier })));
    }
  }

  // ---------- view 3: evidence passages ----------
  const GROUPS = [['liquidity', 'Liquidity and funding'], ['risk', 'Risk factors added or removed'], ['guidance', 'Guidance'], ['driver', 'Drivers: headwinds and tailwinds']];
  const W3 = { key: null, type: 'all' };
  const nice = s => s ? s.replace(/_/g, ' ').replace(/^./, c => c.toUpperCase()) : '';
  function renderEvidence(key) {
    if (key) W3.key = decodeURIComponent(key);
    const shown = CQ.dry.reduce((a, d) => a + d.items.length, 0);
    const list = CQ.dry.slice().sort((x, y) => x.fd.localeCompare(y.fd));
    view.innerHTML = `
      <div class="head-row"><div><div class="eyebrow">3 &middot; Evidence passages</div><h1>Every count backed by the company's own words</h1></div><span class="badge sample">Example from the research sample</span></div>
      <p class="lede">For each credit-relevant disclosure the reading lists the exact sentence from the filing, and every quote is checked word for word against the filing text. Below: ${shown} verified quotes from ${CQ.dry.length} filings made from 2021 to 2024.</p>
      <div class="rule"><b>Example from the research sample.</b> These are real quotes from real filings, extracted in the research test run. ${M.dry_unverified} of the ${M.dry_total} extracted quotes failed the word-for-word check and are not shown. Quotes for the current-quarter filings are not part of this mock-up.</div>
      <div class="controls"><div class="seg" id="evtype">${[['all', 'All types']].concat(GROUPS.map(g => [g[0], g[1].split(':')[0]])).map(([k, l]) => `<button data-k="${k}" class="${W3.type === k ? 'on' : ''}">${esc(l)}</button>`).join('')}</div></div>
      <div class="ev-layout">
        <div class="ev-list" id="evlist"><button data-key="" class="${!W3.key ? 'on' : ''}"><span class="t">All ${CQ.dry.length} filings</span><span class="s">${shown} quotes</span></button>
          ${list.map(d => `<button data-key="${esc(d.key)}" class="${W3.key === d.key ? 'on' : ''}"><span class="t">${esc(d.t)}</span> <span class="muted">${esc(d.fd)}</span><span class="s">${esc(d.n)} &middot; ${d.items.length} quotes</span></button>`).join('')}</div>
        <div id="evbody"></div>
      </div>`;
    document.getElementById('evtype').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; W3.type = b.dataset.k;
      [...document.querySelectorAll('#evtype button')].forEach(x => x.classList.toggle('on', x === b)); fillEvidence(); });
    document.getElementById('evlist').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; W3.key = b.dataset.key || null;
      [...document.querySelectorAll('#evlist button')].forEach(x => x.classList.toggle('on', x === b)); fillEvidence(); });
    fillEvidence();
  }
  function fillEvidence() {
    const ds = W3.key ? CQ.dry.filter(d => d.key === W3.key) : CQ.dry;
    const items = ds.flatMap(d => d.items.map(it => Object.assign({ d }, it)));
    const head = W3.key && ds[0] ? `<div class="panel" style="margin-bottom:16px"><h2>${esc(ds[0].n)} (${esc(ds[0].t)})</h2><div class="sub" style="margin:0">Filing of ${esc(ds[0].fd)}, ${esc(studyName(ds[0].study))} study. ${ds[0].items.length} verified quotes${ds[0].unverified ? `; ${ds[0].unverified} failed verification and are hidden` : ''}.${latest.has(ds[0].t) ? ` <a href="#company/${esc(latest.get(ds[0].t).acc)}">Current-quarter company view</a>` : ''}</div></div>` : '';
    const groups = GROUPS.filter(g => W3.type === 'all' || W3.type === g[0]).map(([k, label]) => {
      const its = items.filter(it => it.type === k);
      if (!its.length) return `<div class="group"><h3>${esc(label)} <span class="c">0</span></h3><p class="muted">No ${k === 'risk' ? 'risk-factor' : esc(label.toLowerCase())} items were extracted ${W3.key ? 'for this filing' : 'for these 20 filings'}.</p></div>`;
      const shown = its.slice(0, W3.key ? 200 : 40);
      return `<div class="group"><h3>${esc(label)} <span class="c">${its.length}</span></h3>${shown.map(it => `<div class="quote"><div class="tags">
          ${!W3.key ? `<span class="tag">${esc(it.d.t)} ${esc(it.d.fd)}</span>` : ''}<span class="tag${k === 'driver' ? ' dir' : ''}">${esc(nice(it.label))}</span>${it.dom ? `<span class="tag">${esc(nice(it.dom))}</span>` : ''}</div>
          <p>${esc(it.q)}${it.q.length >= 200 ? ' ...' : ''}</p><div class="ver">Quote verified against the filing text${it.q.length >= 200 ? '; shown as stored in the research extract, which keeps the first 200 characters' : ''}</div></div>`).join('')}
          ${its.length > shown.length ? `<p class="muted">${its.length - shown.length} more in this group: pick a single filing on the left to see all of them.</p>` : ''}</div>`;
    }).join('');
    document.getElementById('evbody').innerHTML = head + groups;
  }
  const studyName = s => ({ dow30: 'Dow 30', ndx100: 'Nasdaq-100', semis: 'semiconductors', financials: 'financials', healthcare: 'healthcare' })[s] || s;

  // ---------- view 4: back-test ----------
  const W4 = { sig: 'Change Signal', h: 12, path: 'Change Signal' };
  const SIGS = ['Change Signal', 'Tone Shift', 'Credit Stress Index'];
  const flip = s => s === 'Change Signal' ? -1 : 1; // Change Signal shown on the watch-list scale: below 0 = worse
  function renderBacktest() {
    view.innerHTML = `
      <div class="eyebrow">4 &middot; Back-test</div><h1>A full quarter of flags, with what happened next</h1>
      <p class="lede">Every rated filing flagged from July to September 2024 by a rule fixed before any outcome was looked at, and whether the company was downgraded by S&amp;P within 12 months. Ratings data end 2025-09-30.</p>
      <div class="controls"><div class="seg" id="bsig">${SIGS.map(s => `<button data-k="${s}" class="${W4.sig === s ? 'on' : ''}">${s} (${CQ.y2.filter(r => r.sig === s).length})</button>`).join('')}</div></div>
      <div class="tiles" id="btiles"></div>
      <div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>Company</th><th class="hide-s">Filed</th><th class="num">Read<span class="hide-s">ing</span></th><th>Outcome<span class="hide-s">, 12 months</span></th><th class="hide-s">Downgrade date</th><th class="num">Lead<span class="hide-s"> (days)</span></th><th class="num hide-m">Deepest 90-day fall</th></tr></thead><tbody id="bbody"></tbody></table></div>
      <div class="limit" id="blimit"></div>

      <div class="panel sec"><div class="head-row"><div><h2>Flagged tenth against all rated filings</h2><div class="sub">Share downgraded within the horizon, out of sample 2021 to mid-2026</div></div>
        <div class="seg" id="bh">${[3, 6, 12].map(h => `<button data-k="${h}" class="${W4.h === h ? 'on' : ''}">${h} months</button>`).join('')}</div></div>
        <div class="legend"><span><i style="background:${C.flag}"></i>Flagged tenth (worst decile)</span><span><i style="background:${C.base}"></i>All rated filings</span></div>
        <div class="chart" id="y1chart"></div>
        <p class="caption" id="y1cap"></p>
        <div class="limit"><b>Limit.</b> Credit controls alone reach an out-of-sample AUC of 0.875 and the text readings add +0.004, not significant. The value is the concentration of downgrades in flagged names and the association beyond controls, not a better rating model.</div>
      </div>

      <div class="panel sec"><div class="head-row"><div><h2>Signal path before downgrades</h2><div class="sub">Average reading by quarter before the downgrade, against matched companies with the same rating that were not downgraded</div></div>
        <div class="seg" id="bpath">${SIGS.map(s => `<button data-k="${s}" class="${W4.path === s ? 'on' : ''}">${s}</button>`).join('')}</div></div>
        <div class="legend"><span><i class="line" style="background:${C.flag}"></i>Later downgraded</span><span><i class="line" style="background:${C.base}"></i>Matched, not downgraded</span></div>
        <div class="chart" id="y3chart"></div>
        <p class="caption" id="y3cap"></p>
        <div class="limit"><b>Limit.</b> These are group averages, not a forecast for one company. The language model may partly remember what happened to these companies: holding a recall probe fixed removes 4% to 10% of the credit effects (all still significant). Filings made after the model's training ended, like the current watch list, are the clean test; they report from 2027.</div>
      </div>`;
    const seg = (id, k, num) => document.getElementById(id).addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; W4[k] = num ? +b.dataset.k : b.dataset.k;
      [...document.querySelectorAll('#' + id + ' button')].forEach(x => x.classList.toggle('on', x === b)); drawBacktest(); });
    seg('bsig', 'sig'); seg('bh', 'h', true); seg('bpath', 'path');
    drawBacktest();
  }
  function drawBacktest() {
    const rows = CQ.y2.filter(r => r.sig === W4.sig).sort((x, y) => y.hit - x.hit || x.fd.localeCompare(y.fd));
    const hits = rows.filter(r => r.hit), base = CQ.y1.find(r => r.sig === W4.sig && r.h === 12 && r.g === 'decile 10').base;
    const leads = hits.map(r => r.lead).filter(v => v != null);
    const dir = W4.sig === 'Change Signal' ? 'below 0 = worse' : 'higher = worse';
    document.getElementById('btiles').innerHTML = `
      <div class="tile"><div class="l">Filings flagged, Jul to Sep 2024</div><div class="v">${rows.length}</div><div class="d">${W4.sig}</div></div>
      <div class="tile"><div class="l">Downgraded within 12 months</div><div class="v">${hits.length}</div><div class="d">${pct(hits.length / rows.length, 0)} of flagged</div></div>
      <div class="tile"><div class="l">Base rate, all rated filings</div><div class="v">${pct(base)}</div><div class="d">downgraded within 12 months</div></div>
      <div class="tile"><div class="l">Median lead of hits</div><div class="v">${leads.length ? median(leads) : 'n/a'} days</div><div class="d">filing to downgrade</div></div>`;
    document.getElementById('bbody').innerHTML = rows.map(r => { const v = r.v * flip(r.sig), cut = r.cut * flip(r.sig);
      return `<tr><td><span class="tk">${esc(r.t)}</span><span class="nm">${esc(r.n)}</span></td><td class="mono hide-s">${esc(r.fd)}</td>
      <td class="num"${tip(`${esc(W4.sig)} ${sgn(v)} (${dir}); flag cut-off ${sgn(cut)}`)}>${sgn(v)}</td>
      <td>${r.hit ? `<span class="badge hit">Downgraded</span>` : '<span class="badge miss">No<span class="hide-s">t downgraded</span></span>'}</td>
      <td class="mono hide-s">${r.dd || ''}</td><td class="num">${r.lead == null ? '' : r.lead + (r.lead < 30 ? ' <span class="muted"' + tip('Too short to count as warning') + '>*</span>' : '')}</td>
      <td class="num hide-m">${r.fall == null ? '<span class="muted">n/a</span>' : pct(r.fall, 0)}</td></tr>`; }).join('');
    document.getElementById('blimit').innerHTML = `<b>Limit.</b> Most flagged names were not downgraded: this is a watch list, not a forecast. ${rows.some(r => r.hit && r.lead < 30) ? 'A downgrade marked * came within days of the filing, too short to count as warning. ' : ''}Reading shown ${dir}. Downgrades are S&amp;P rating changes; one quarter is an illustration, the decile tables below are the evidence.`;

    const g = SIGS.map(s => { const d = CQ.y1.find(r => r.sig === s && r.h === W4.h && r.g === 'decile 10');
      return { label: s, sub: `${d.n.toLocaleString('en-US')} flagged filings`, subShort: `n = ${d.n.toLocaleString('en-US')}`, a: d.rate, b: d.base,
        tipA: `<b>${s}, flagged tenth</b><br>${pct(d.rate)} downgraded within ${W4.h} months (${d.dg} of ${d.n})<br><span class="m">${d.lift.toFixed(1)} times the base rate (90% interval ${d.lo.toFixed(1)} to ${d.hi.toFixed(1)}); ${pct(d.rec, 0)} of all downgrades</span>`,
        tipB: `<b>${s}, all rated filings</b><br>${pct(d.base)} downgraded within ${W4.h} months` }; });
    groupedBars(document.getElementById('y1chart'), g, { label: 'Downgrade rate of flagged tenth against all filings' });
    const cs = g[0];
    document.getElementById('y1cap').textContent = `Within ${W4.h} months, ${pct(cs.a)} of filings in the worst tenth of the Change Signal were followed by a downgrade, against ${pct(cs.b)} of all rated filings (${(cs.a / cs.b).toFixed(1)} times as often).`;

    const ys = CQ.y3.filter(r => r.sig === W4.path), k = flip(W4.path);
    const xs = [-4, -3, -2, -1, 0].map(q => ({ long: q === 0 ? 'Downgrade quarter' : `${-q} quarter${q === -1 ? '' : 's'} before`, short: q === 0 ? 'Q0' : `Q${q}` }));
    const ser = (gname, name, color) => { const r = [-4, -3, -2, -1, 0].map(q => ys.find(x => x.g === gname && x.q === q)); return { name, color, values: r.map(x => x.m * k), ns: r.map(x => x.n) }; };
    const S = [ser('downgrade', 'Later downgraded', C.flag), ser('matched, no downgrade', 'Matched, not downgraded', C.base)];
    lineChart(document.getElementById('y3chart'), xs, S, { label: 'Signal path before downgrades', step: W4.path === 'Credit Stress Index' ? 0.5 : 0.1, dp: W4.path === 'Credit Stress Index' ? 1 : 2 });
    const ev = ys[0].ev;
    document.getElementById('y3cap').textContent = `${W4.path} (${W4.path === 'Change Signal' ? 'below 0 = worse' : 'higher = worse'}), ${ev} downgrades: four quarters ahead the later-downgraded companies averaged ${sgn(S[0].values[0], 3)} against ${sgn(S[1].values[0], 3)} for matched companies; in the downgrade quarter ${sgn(S[0].values[4], 3)} against ${sgn(S[1].values[4], 3)}.`;
  }

  // ---------- view 5: portfolio ----------
  let W5 = M.sample_portfolio.join(', ');
  function renderPortfolio() {
    view.innerHTML = `
      <div class="eyebrow">5 &middot; Portfolio check</div><h1>Which of my holdings are flagged, and why</h1>
      <p class="lede">Paste tickers separated by commas, spaces or new lines. Each holding is matched to its latest filing in the current set (${M.filed_from} to ${M.filed_to}).</p>
      <div class="panel sec"><label class="muted" for="ptext">Holdings</label>
        <textarea id="ptext" spellcheck="false" style="margin-top:6px">${esc(W5)}</textarea>
        <div class="controls" style="margin:10px 0 0"><button class="btn" id="pgo">Check holdings</button><button class="btn ghost" id="preset">Reset to sample</button><span class="count">Sample: 10 real tickers from the current set</span></div>
      </div>
      <div id="pout"></div>`;
    document.getElementById('pgo').addEventListener('click', () => { W5 = document.getElementById('ptext').value; fillPortfolio(); });
    document.getElementById('preset').addEventListener('click', () => { W5 = M.sample_portfolio.join(', '); document.getElementById('ptext').value = W5; fillPortfolio(); });
    fillPortfolio();
  }
  function reasons(f) {
    const r = [];
    if (f.fc) { const top = f.cnt.map((c, i) => [c, i]).filter(([c, i]) => c > 0 && c >= cntP90[i] && i !== 6 && i !== 4);
      r.push(`<b>Credit Stress Index ${sgn(f.csi)}</b>, rank ${f.rank} of ${F.length}` + (top.length ? `; top tenth of the set for ${top.map(([c, i]) => `${CNT_SHORT[i]} (${c})`).join(', ')}` : '')); }
    if (f.fs) r.push(`<b>Change Signal ${sgn(f.cs)}</b>: reads worse than the previous filing (cut-off ${sgn(M.cs_cut)})`);
    const items = f.cnt.map((c, i) => c ? `${c} ${CNT_SHORT[i]}` : '').filter(Boolean).join(', ');
    r.push(`<span class="muted">Items counted: ${items || 'none'}</span>`);
    return r.join('<br>');
  }
  function fillPortfolio() {
    const toks = [...new Set((W5.toUpperCase().match(/[A-Z][A-Z0-9.\-]{0,9}/g) || []))];
    const found = toks.map(t => latest.get(t)).filter(Boolean), missing = toks.filter(t => !latest.has(t));
    found.sort((x, y) => (y.fc + y.fs) - (x.fc + x.fs) || y.csi - x.csi);
    const nAny = found.filter(f => f.fc || f.fs).length;
    document.getElementById('pout').innerHTML = `
      <div class="tiles">
        <div class="tile"><div class="l">Holdings matched</div><div class="v">${found.length}</div><div class="d">of ${toks.length} entered</div></div>
        <div class="tile"><div class="l">Flagged by either reading</div><div class="v">${nAny}</div><div class="d">${found.length ? pct(nAny / found.length, 0) : 'n/a'} of matched; ${pct(M.n_flag_any / M.n_filings, 0)} across the set</div></div>
        <div class="tile"><div class="l">Flagged by Credit Stress Index</div><div class="v">${found.filter(f => f.fc).length}</div><div class="d">worst tenth of the set</div></div>
        <div class="tile"><div class="l">Flagged by Change Signal</div><div class="v">${found.filter(f => f.fs).length}</div><div class="d">worse than the last filing</div></div>
      </div>
      ${found.length ? `<p class="caption">${nAny ? `${nAny} of ${found.length} holdings ${nAny === 1 ? 'deserves' : 'deserve'} a closer look: ${found.filter(f => f.fc || f.fs).map(f => esc(f.t)).join(', ')}.` : 'None of these holdings is flagged in the current set.'} A flag is a reason to read the filing, not a rating or a sell signal.</p>` : ''}
      ${missing.length ? `<p class="muted" style="margin-top:8px">Not in the current set: ${missing.map(esc).join(', ')}.</p>` : ''}
      ${found.length ? `<div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Holding</th><th class="hide-m">Latest filing</th><th class="hide-s">Credit Stress Index</th><th class="hide-s">Change Signal</th><th>Status and reason</th></tr></thead><tbody>
      ${found.map(f => `<tr class="click" data-acc="${esc(f.acc)}"><td><span class="tk">${esc(f.t)}</span><span class="nm">${esc(f.n)}</span></td><td class="mono hide-m">${esc(f.form)} ${esc(f.fd)}</td>
        <td class="hide-s">${ibar(f.csi, 8.5, f.fc, csiTip(f))}</td><td class="hide-s">${ibar(f.cs, 1, f.fs, csTip(f), 2)}</td>
        <td><div class="badges" style="margin-bottom:4px">${flagBadges(f) || '<span class="badge ok">Not flagged</span>'}</div><div class="reason">${reasons(f)}</div></td></tr>`).join('')}
      </tbody></table></div>` : ''}`;
    const tb = document.querySelector('#pout tbody'); if (tb) tb.addEventListener('click', e => { const tr = e.target.closest('tr[data-acc]'); if (tr) location.hash = '#company/' + tr.dataset.acc; });
  }

  // ---------- view 6: sector risk map ----------
  function renderSectors() {
    const keys = Object.keys(CQ.sectors);
    const cols = [
      { h: 'Filings now', get: k => sectorStats[k].n, fmt: v => String(v), dir: 0 },
      { h: 'CSI flagged', get: k => sectorStats[k].n ? sectorStats[k].fc / sectorStats[k].n : null, fmt: v => pct(v, 0), dir: 1, note: k => `${sectorStats[k].fc} of ${sectorStats[k].n} current filings` },
      { h: 'Change flagged', get: k => sectorStats[k].n ? sectorStats[k].fs / sectorStats[k].n : null, fmt: v => pct(v, 0), dir: 1, note: k => `${sectorStats[k].fs} of ${sectorStats[k].n} current filings` },
      { h: 'Volatility', get: k => CQ.sectors[k].vol[1], fmt: v => pct(v, 0), dir: 1, rng: 'vol', rf: v => pct(v, 0) },
      { h: '250-day fall', get: k => CQ.sectors[k].fall[1], fmt: v => pct(v, 0), dir: -1, rng: 'fall', rf: v => pct(v, 0) },
      { h: 'Distance to default', get: k => CQ.sectors[k].dd[1], fmt: v => fx(v, 1), dir: -1, rng: 'dd', rf: v => fx(v, 1) },
      { h: 'Altman Z', get: k => CQ.sectors[k].altman[1], fmt: v => fx(v, 2), dir: -1, rng: 'altman', rf: v => fx(v, 2) },
      { h: 'Leverage', get: k => CQ.sectors[k].lev[1], fmt: v => fx(v, 2), dir: 1, rng: 'lev', rf: v => fx(v, 2) }];
    cols.forEach(c => { if (!c.dir) return; const vals = keys.map(c.get).filter(v => v != null); c.lo = Math.min(...vals); c.hi = Math.max(...vals); });
    const shade = (c, v) => { if (!c.dir || v == null || c.hi === c.lo) return ''; let t = (v - c.lo) / (c.hi - c.lo); if (c.dir < 0) t = 1 - t; return `background:rgba(91,141,217,${(0.05 + 0.45 * t).toFixed(3)})`; };
    const order = keys.slice().sort((a, b) => (sectorStats[b].any / (sectorStats[b].n || 1)) - (sectorStats[a].any / (sectorStats[a].n || 1)));
    view.innerHTML = `
      <div class="eyebrow">6 &middot; Sector risk map</div><h1>Where the current flags sit, against each sector's risk profile</h1>
      <p class="lede">Share of the current quarter's filings flagged in each sector, next to the sector's market and credit fundamentals from the research sample (medians across 2015 to 2026). Sorted by share flagged by either reading. Click a sector to open its watch list.</p>
      <div class="controls"><span class="scale">Shading within each column, darker = riskier:</span>${[0.05, 0.2, 0.35, 0.5].map(a => `<span class="scale"><span class="sw" style="background:rgba(91,141,217,${a})"></span></span>`).join('')}<span class="scale">lower risk to higher risk</span></div>
      <div class="table-wrap"><table class="heatmap"><thead><tr><th>Sector</th>${cols.map(c => `<th class="num">${c.h}</th>`).join('')}</tr></thead><tbody>
      ${order.map(k => `<tr class="click" data-sec="${k}"><td><span style="color:var(--text-primary)">${esc(SECTOR(k))}</span><span class="nm">${CQ.sectors[k].cos} companies in research sample</span></td>
        ${cols.map(c => { const v = c.get(k); const t = c.rng ? `<b>${esc(SECTOR(k))}</b>: ${c.h} median ${c.fmt(v)}<br><span class="m">10th to 90th percentile ${c.rf(CQ.sectors[k][c.rng][0])} to ${c.rf(CQ.sectors[k][c.rng][2])}; ${CQ.sectors[k].fil.toLocaleString('en-US')} filings</span>` : c.note ? `<b>${esc(SECTOR(k))}</b>: ${c.note(k)}${sectorStats[k].n < 20 ? '<br><span class="m">Few filings: read the share with care</span>' : ''}` : `<b>${esc(SECTOR(k))}</b>: ${v} filings in the current set`;
          return `<td class="heat" style="${shade(c, v)}"${tip(t)}>${v == null ? 'n/a' : c.fmt(v)}</td>`; }).join('')}</tr>`).join('')}
      </tbody></table></div>
      <p class="muted" style="margin-top:12px">Sectors are the Fama-French 12 industry groups. Volatility is the 250-day close-to-close volatility, annualised. Distance to default follows Bharath and Shumway. Across the whole set, ${pct(M.n_flag_csi / M.n_filings, 0)} of filings are flagged by the Credit Stress Index and ${pct(M.n_flag_cs / M.n_filings, 0)} by the Change Signal. Sectors with few current filings (Chemicals 8, Energy 12, Consumer durables 14) swing on one or two names.</p>`;
    document.querySelector('tbody').addEventListener('click', e => { const tr = e.target.closest('tr[data-sec]'); if (!tr) return; W1.sec = tr.dataset.sec; W1.flag = 'all'; W1.q = ''; W1.shown = 100; location.hash = '#watch'; });
  }

  // ---------- view 7: alerts ----------
  const W7 = { csi: true, cs: true, thr: 0.1, secs: new Set(Object.keys(CQ.sectors)), delivery: 'email', freq: 'filing' };
  function renderAlerts() {
    const sample = F.find(f => f.fc && f.fs);
    view.innerHTML = `
      <div class="eyebrow">7 &middot; Alerts</div><h1>Get told when a filing turns worse</h1>
      <p class="lede">Preview of the alert settings. The preview count uses the real current-quarter readings; nothing is saved or sent.</p>
      <div class="grid2 sec">
        <div class="panel"><h2>Alert settings</h2><div class="sub">Applies to every new filing in your coverage</div>
          <div class="form-grid">
            <div class="field"><label class="h">Readings</label><div class="checks"><label><input type="checkbox" id="acsi"${W7.csi ? ' checked' : ''}> Credit Stress Index</label><label><input type="checkbox" id="acs"${W7.cs ? ' checked' : ''}> Change Signal</label></div></div>
            <div class="field"><label class="h" for="athr">Threshold</label><select id="athr"><option value="0.05">Worst 5% of filings</option><option value="0.1">Worst tenth of filings (research rule)</option><option value="0.2">Worst fifth of filings</option></select></div>
            <div class="field"><label class="h">Sectors</label><div class="checks" id="asecs">${Object.keys(CQ.sectors).map(k => `<label><input type="checkbox" value="${k}"${W7.secs.has(k) ? ' checked' : ''}> ${esc(SECTOR(k))}</label>`).join('')}</div></div>
            <div class="field"><label class="h">Delivery</label><div class="checks" id="adel">${[['email', 'Email'], ['api', 'API (JSON)'], ['webhook', 'Webhook']].map(([k, l]) => `<label><input type="radio" name="adel" value="${k}"${W7.delivery === k ? ' checked' : ''}> ${l}</label>`).join('')}</div>
              <input type="email" id="aemail" placeholder="name@yourfirm.com" style="margin-top:8px;width:100%;max-width:320px" aria-label="Email address"></div>
            <div class="field"><label class="h" for="afreq">Frequency</label><select id="afreq"><option value="filing">On each new filing</option><option value="daily">Daily digest</option><option value="weekly">Weekly digest</option></select></div>
            <div><button class="btn" id="asave">Save alert</button><div class="toast" id="atoast"></div></div>
          </div>
        </div>
        <div>
          <div class="panel"><h2>Preview on the current quarter</h2><div class="sub">Filings from ${M.filed_from} to ${M.filed_to} that these settings would have sent</div>
            <div class="preview-n" id="an"></div><div class="muted" id="anote"></div></div>
          <div class="panel"><h2>Sample alert</h2><div class="sub">Built from a real flagged filing in the current set: the highest Credit Stress Index among filings flagged by both readings</div>
            <div class="alert-card">
              <div class="ah"><span>ContextQuant alert &middot; ${esc(sample.fd)}</span><span class="badges">${flagBadges(sample)}</span></div>
              <div class="ab"><h3>${esc(sample.n)} (${esc(sample.t)})</h3><div class="muted">${esc(sample.form)} filed ${esc(sample.fd)} &middot; ${esc(SECTOR(sample.sec))}</div>
                <div class="kv">
                  <span class="k">Credit Stress Index</span><span class="v">${sgn(sample.csi)}, rank ${sample.rank} of ${F.length} (sector median ${sgn(sectorStats[sample.sec].csiMed)})</span>
                  <span class="k">Change Signal</span><span class="v">${sgn(sample.cs)}, reads worse than the previous filing</span>
                  <span class="k">Items counted</span><span class="v">${sample.cnt.map((c, i) => c ? `${c} ${CNT_SHORT[i]}` : '').filter(Boolean).join(', ')}</span>
                  <span class="k">Evidence</span><span class="v"><span class="muted">In the product, each counted item links to the quoted passage in the filing.</span></span>
                </div>
                <div class="controls" style="margin:14px 0 0"><a class="btn ghost" href="#company/${esc(sample.acc)}" style="text-decoration:none">Open company view</a></div>
              </div>
            </div>
            <div class="sub" style="margin:14px 0 6px">Same alert as an API payload</div>
            <pre class="json">${esc(JSON.stringify({ type: 'filing_flagged', ticker: sample.t, company: sample.n, form: sample.form, filed: sample.fd,
              readings: { credit_stress_index: sample.csi, csi_rank: sample.rank, change_signal: sample.cs }, flags: [sample.fc && 'credit_stress_index', sample.fs && 'change_signal'].filter(Boolean),
              items: Object.fromEntries(CNT_SHORT.map((l, i) => [l.replace(/ /g, '_'), sample.cnt[i]])), evidence_url: '(link to quoted passages in the product)' }, null, 2))}</pre>
          </div>
        </div>
      </div>`;
    document.getElementById('athr').value = String(W7.thr); document.getElementById('afreq').value = W7.freq;
    const upd = () => {
      W7.csi = document.getElementById('acsi').checked; W7.cs = document.getElementById('acs').checked; W7.thr = +document.getElementById('athr').value;
      W7.secs = new Set([...document.querySelectorAll('#asecs input:checked')].map(i => i.value));
      const d = document.querySelector('#adel input:checked'); W7.delivery = d ? d.value : 'email'; W7.freq = document.getElementById('afreq').value;
      document.getElementById('aemail').style.display = W7.delivery === 'email' ? '' : 'none';
      const cc = W7.thr === 0.1 ? M.csi_cut : quantile(allCsi, 1 - W7.thr), sc = W7.thr === 0.1 ? M.cs_cut : quantile(allCs, W7.thr);
      const n = F.filter(f => W7.secs.has(String(f.sec)) && ((W7.csi && (W7.thr === 0.1 ? f.fc : f.csi >= cc)) || (W7.cs && (W7.thr === 0.1 ? f.fs : f.cs <= sc)))).length;
      document.getElementById('an').textContent = `${n} filing${n === 1 ? '' : 's'}`;
      document.getElementById('anote').textContent = `About ${(n / 4).toFixed(0)} a month over four months. Cut-offs: Credit Stress Index at or above ${fx(cc)}, Change Signal at or below ${fx(sc)}, ties included.`;
    };
    view.querySelectorAll('input, select').forEach(i => i.addEventListener('change', upd));
    document.getElementById('asave').addEventListener('click', () => { document.getElementById('atoast').textContent = 'Preview only: settings are not saved and no alert is sent.'; });
    upd();
  }

  // ---------- router ----------
  let lastW = window.innerWidth;
  function route() {
    tipEl.style.display = 'none';
    const h = location.hash.replace(/^#/, ''); const [v, arg] = [h.split('/')[0] || 'watch', h.split('/').slice(1).join('/')];
    document.querySelectorAll('#sidenav a').forEach(a => a.classList.toggle('active', a.dataset.view === v));
    const act = document.querySelector('#sidenav a.active'); if (act && act.scrollIntoView && window.innerWidth <= 820) act.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    if (v === 'company') renderCompany(arg);
    else if (v === 'evidence') renderEvidence(arg);
    else if (v === 'backtest') renderBacktest();
    else if (v === 'portfolio') renderPortfolio();
    else if (v === 'sectors') renderSectors();
    else if (v === 'alerts') renderAlerts();
    else renderWatch();
    window.scrollTo(0, 0);
  }
  window.addEventListener('hashchange', route);
  let rt; window.addEventListener('resize', () => { if (Math.abs(window.innerWidth - lastW) < 40) return; lastW = window.innerWidth; clearTimeout(rt);
    rt = setTimeout(() => { const v = (location.hash.replace(/^#/, '').split('/')[0]) || 'watch'; if (v === 'company' || v === 'backtest') route(); }, 200); });
  route();
})();
